1	'use client';
2	
3	import { DUE_LIST_MODELO_ALL, DUE_LIST_MODELO_DEFAULT } from '@/constants/due-diligence-query';
4	import {
5	    buildDueDiligenceListApiFilters,
6	    buildOperationalListFiltersFromInput,
7	    resolveDueListModeloScope,
8	} from '@/functions/juridico/dueListOperationalFilters';
9	import { useUserInfoStore } from '@/store/userInfo';
10	import type { IOperationalListFilterInput, TDueModeloFilter } from '@/types/due-list-filters';
11	import type { Filter } from '@/types/filter';
12	import { parseAsInteger, parseAsString, parseAsStringEnum, useQueryStates } from 'nuqs';
13	import { useMemo } from 'react';
14	import {
15	    LIQUIDACAO_LIST_VIEW_MODE_DEFAULT,
16	    LIQUIDACAO_LIST_VIEW_MODES,
17	} from '../constants/liquidacaoListViewMode';
18	import {
19	    DueDiligenceFilterType,
20	    LiquidacaoFilterType,
21	    normalizeDueListFilterFromUrl,
22	    normalizeLiquidacaoListFilterFromUrl,
23	} from '../interfaces/store';
24	import { liquidacaoTabToStatusLiquidacaoQueryValue } from '../services/LiquidacaoScreenService';
25	import type { TLiquidacaoListViewMode } from '../types/liquidacaoKanban';
26	import { resolveLockedCoordinatorUsername } from '../utils/dueCoordinatorAccess';
27	import { normalizeLiquidacaoFunilSubstatusFromUrl } from '../utils/liquidacaoSubstatusFunnel';
28	
29	export function useOperationalListFilterQueryState() {
30	    const currentUsername = useUserInfoStore(
31	        (state) => state.data.username || state.data.user,
32	    );
33	    const userRole = useUserInfoStore((state) => state.data.role);
34	    const lockedCoordinatorUsername = resolveLockedCoordinatorUsername(userRole, {
35	        user: currentUsername,
36	        username: currentUsername
37	    });
38	
39	    const [queryStates, setQueryStates] = useQueryStates({
40	        filter: parseAsString.withDefault('TODOS' as DueDiligenceFilterType),
41	        liqFilter: parseAsString.withDefault('TODOS' as LiquidacaoFilterType),
42	        modelo: parseAsString.withDefault(DUE_LIST_MODELO_DEFAULT),
43	        loa: parseAsString,
44	        credor: parseAsString,
45	        broker: parseAsString,
46	        priority_level: parseAsString,
47	        responsavel_scope: parseAsString,
48	        investidor_scope: parseAsString,
49	        investidor: parseAsString,
50	        esfera: parseAsString,
51	        ente_devedor: parseAsString,
52	        estado_ente_devedor: parseAsString,
53	        coordenador: parseAsString,
54	        host: parseAsString,
55	        liqSubStatus: parseAsString,
56	        page: parseAsInteger.withDefault(1),
57	        dataView: parseAsStringEnum([
58	            ...LIQUIDACAO_LIST_VIEW_MODES,
59	        ]).withDefault(LIQUIDACAO_LIST_VIEW_MODE_DEFAULT),
60	    });
61	
62	    // Sem host explícito, o backend resolve o escopo (host próprio + hosts delegadores).
63	    const explicitHost = queryStates.host?.trim() || null;
64	
65	    const operationalInput = useMemo<IOperationalListFilterInput>(
66	        () => ({
67	            modelo: resolveDueListModeloScope(queryStates.modelo),
68	            loa: queryStates.loa,
69	            credor: queryStates.credor,
70	            broker: queryStates.broker,
71	            priority_level: queryStates.priority_level,
72	            responsavel_scope: queryStates.responsavel_scope,
73	            investidor_scope: queryStates.investidor_scope,
74	            investidor: queryStates.investidor,
75	            esfera: queryStates.esfera,
76	            ente_devedor: queryStates.ente_devedor,
77	            estado_ente_devedor: queryStates.estado_ente_devedor,
78	            coordenador: lockedCoordinatorUsername ?? queryStates.coordenador,
79	            host: explicitHost,
80	        }),
81	        [
82	            queryStates.modelo,
83	            queryStates.loa,
84	            queryStates.credor,
85	            queryStates.broker,
86	            queryStates.priority_level,
87	            queryStates.responsavel_scope,
88	            queryStates.investidor_scope,
89	            queryStates.investidor,
90	            queryStates.esfera,
91	            queryStates.ente_devedor,
92	            queryStates.estado_ente_devedor,
93	            queryStates.coordenador,
94	            lockedCoordinatorUsername,
95	            explicitHost,
96	        ],
97	    );
98	
99	    const modeloScope = resolveDueListModeloScope(queryStates.modelo);
100	    const dueFase = normalizeDueListFilterFromUrl(queryStates.filter);
101	    const liquidacaoFase = normalizeLiquidacaoListFilterFromUrl(queryStates.liqFilter);
102	    const liquidacaoSubstatus = normalizeLiquidacaoFunilSubstatusFromUrl(queryStates.liqSubStatus);
103	    const page = Math.max(1, queryStates.page ?? 1);
104	    const viewMode = queryStates.dataView ?? LIQUIDACAO_LIST_VIEW_MODE_DEFAULT;
105	
106	    const dueListApiFilters = useMemo(
107	        () => buildDueDiligenceListApiFilters(dueFase, operationalInput, currentUsername),
108	        [dueFase, operationalInput, currentUsername],
109	    );
110	
111	    const liquidacaoListApiFilters = useMemo(() => {
112	        const filters = buildOperationalListFiltersFromInput(operationalInput, currentUsername);
113	        const statusLiquidacao = liquidacaoTabToStatusLiquidacaoQueryValue(liquidacaoFase);
114	        if (statusLiquidacao) {
115	            filters.push({
116	                id: 'status_liquidacao',
117	                label: 'Status Liquidacao',
118	                value: statusLiquidacao,
119	            });
120	        }
121	        if (liquidacaoSubstatus) {
122	            filters.push({
123	                id: 'sub_status',
124	                label: 'Sub status',
125	                value: liquidacaoSubstatus,
126	            });
