'use client';

import { DUE_LIST_MODELO_ALL, DUE_LIST_MODELO_DEFAULT } from '@/constants/due-diligence-query';
import {
    buildDueDiligenceListApiFilters,
    buildOperationalListFiltersFromInput,
    resolveDueListModeloScope,
} from '@/functions/juridico/dueListOperationalFilters';
import { useUserInfoStore } from '@/store/userInfo';
import type { IOperationalListFilterInput, TDueModeloFilter } from '@/types/due-list-filters';
import type { Filter } from '@/types/filter';
import { parseAsInteger, parseAsString, parseAsStringEnum, useQueryStates } from 'nuqs';
import { useMemo } from 'react';
import {
    LIQUIDACAO_LIST_VIEW_MODE_DEFAULT,
    LIQUIDACAO_LIST_VIEW_MODES,
} from '../constants/liquidacaoListViewMode';
import {
    DueDiligenceFilterType,
    LiquidacaoFilterType,
    normalizeDueListFilterFromUrl,
    normalizeLiquidacaoListFilterFromUrl,
} from '../interfaces/store';
import { liquidacaoTabToStatusLiquidacaoQueryValue } from '../services/LiquidacaoScreenService';
import type { TLiquidacaoListViewMode } from '../types/liquidacaoKanban';
import { resolveLockedCoordinatorUsername } from '../utils/dueCoordinatorAccess';
import { normalizeLiquidacaoFunilSubstatusFromUrl } from '../utils/liquidacaoSubstatusFunnel';

export function useOperationalListFilterQueryState() {
    const currentUsername = useUserInfoStore(
        (state) => state.data.username || state.data.user,
    );
    const userRole = useUserInfoStore((state) => state.data.role);
    const lockedCoordinatorUsername = resolveLockedCoordinatorUsername(userRole, {
        user: currentUsername,
        username: currentUsername
    });

    const [queryStates, setQueryStates] = useQueryStates({
        filter: parseAsString.withDefault('TODOS' as DueDiligenceFilterType),
        liqFilter: parseAsString.withDefault('TODOS' as LiquidacaoFilterType),
        modelo: parseAsString.withDefault(DUE_LIST_MODELO_DEFAULT),
        loa: parseAsString,
        credor: parseAsString,
        broker: parseAsString,
        priority_level: parseAsString,
        responsavel_scope: parseAsString,
        investidor_scope: parseAsString,
        investidor: parseAsString,
        esfera: parseAsString,
        ente_devedor: parseAsString,
        estado_ente_devedor: parseAsString,
        coordenador: parseAsString,
        host: parseAsString,
        liqSubStatus: parseAsString,
        page: parseAsInteger.withDefault(1),
        dataView: parseAsStringEnum([
            ...LIQUIDACAO_LIST_VIEW_MODES,
        ]).withDefault(LIQUIDACAO_LIST_VIEW_MODE_DEFAULT),
    });

    // Sem host explícito, o backend resolve o escopo (host próprio + hosts delegadores).
    const explicitHost = queryStates.host?.trim() || null;

    const operationalInput = useMemo<IOperationalListFilterInput>(
        () => ({
            modelo: resolveDueListModeloScope(queryStates.modelo),
            loa: queryStates.loa,
            credor: queryStates.credor,
            broker: queryStates.broker,
            priority_level: queryStates.priority_level,
            responsavel_scope: queryStates.responsavel_scope,
            investidor_scope: queryStates.investidor_scope,
            investidor: queryStates.investidor,
            esfera: queryStates.esfera,
            ente_devedor: queryStates.ente_devedor,
            estado_ente_devedor: queryStates.estado_ente_devedor,
            coordenador: lockedCoordinatorUsername ?? queryStates.coordenador,
            host: explicitHost,
        }),
        [
            queryStates.modelo,
            queryStates.loa,
            queryStates.credor,
            queryStates.broker,
            queryStates.priority_level,
            queryStates.responsavel_scope,
            queryStates.investidor_scope,
            queryStates.investidor,
            queryStates.esfera,
            queryStates.ente_devedor,
            queryStates.estado_ente_devedor,
            queryStates.coordenador,
            lockedCoordinatorUsername,
            explicitHost,
        ],
    );

    const modeloScope = resolveDueListModeloScope(queryStates.modelo);
    const dueFase = normalizeDueListFilterFromUrl(queryStates.filter);
    const liquidacaoFase = normalizeLiquidacaoListFilterFromUrl(queryStates.liqFilter);
    const liquidacaoSubstatus = normalizeLiquidacaoFunilSubstatusFromUrl(queryStates.liqSubStatus);
    const page = Math.max(1, queryStates.page ?? 1);
    const viewMode = queryStates.dataView ?? LIQUIDACAO_LIST_VIEW_MODE_DEFAULT;

    const dueListApiFilters = useMemo(
        () => buildDueDiligenceListApiFilters(dueFase, operationalInput, currentUsername),
        [dueFase, operationalInput, currentUsername],
    );

    const liquidacaoListApiFilters = useMemo(() => {
        const filters = buildOperationalListFiltersFromInput(operationalInput, currentUsername);
        const statusLiquidacao = liquidacaoTabToStatusLiquidacaoQueryValue(liquidacaoFase);
        if (statusLiquidacao) {
            filters.push({
                id: 'status_liquidacao',
                label: 'Status Liquidacao',
                value: statusLiquidacao,
            });
        }
        if (liquidacaoSubstatus) {
            filters.push({
                id: 'sub_status',
                label: 'Sub status',
                value: liquidacaoSubstatus,
            });
        }
        return filters;
    }, [liquidacaoFase, liquidacaoSubstatus, operationalInput, currentUsername]);

    const operationalListApiFilters = useMemo(
        () => buildOperationalListFiltersFromInput(operationalInput, currentUsername),
        [operationalInput, currentUsername],
    );

    const listQueryFingerprint = useMemo(
        () =>
            JSON.stringify({
                dueFase,
                liquidacaoFase,
                liquidacaoSubstatus,
                operationalInput,
            }),
        [dueFase, liquidacaoFase, liquidacaoSubstatus, operationalInput],
    );

    return {
        queryStates,
        operationalInput,
        dueFase,
        liquidacaoFase,
        modeloScope,
        page,
        setPage: (nextPage: number) => {
            void setQueryStates({ page: nextPage });
        },
        toggleModelo: (modelo: TDueModeloFilter) => {
            const nextModelo = modeloScope === modelo ? DUE_LIST_MODELO_ALL : modelo;
            void setQueryStates({ modelo: nextModelo, page: 1 });
        },
        viewMode,
        setViewMode: (nextViewMode: TLiquidacaoListViewMode) => {
            void setQueryStates({ dataView: nextViewMode });
        },
        dueListApiFilters,
        liquidacaoListApiFilters,
        operationalListApiFilters,
        listQueryFingerprint,
        buildOperationalFilters: (): Filter[] => operationalListApiFilters,
    };
}
